/*
 * Atelier — Krackle grid empty states
 * Classic-script IIFE adding window.AtelierMotion.emptyState.
 * Kinds: empty (an empty folder: a tray with two bubbles dropped in), none (no
 * matches: three loose bubbles bounce to the floor) and error (the folder could
 * not load: a splat). One short entrance, then still; no idle loop.
 * Artwork is generated by scripts/krackle_art.py, which also writes empty-state.svg.
 */
(function () {
  'use strict';

  var KINDS = new Set(['empty', 'none', 'error']);
  var EASE_STANDARD = 'cubic-bezier(0.2, 0, 0, 1)';
  var EASE_FALL = 'cubic-bezier(0.55, 0, 1, 0.45)';
  var EASE_RISE = 'cubic-bezier(0, 0.55, 0.45, 1)';
  var mounted = typeof WeakMap === 'function' ? new WeakMap() : null;

  // krackle-art:empty-state:begin
  var SVG_MARKUP = '<svg xmlns="http://www.w3.org/2000/svg" class="am-empty-state-svg" viewBox="0 0 64 64" width="64" height="64" aria-hidden="true" focusable="false" fill="currentColor"><g class="am-empty-state-kind am-empty-state-kind-empty"><g class="am-empty-state-tray"><path class="am-empty-state-energy am-empty-state-well" d="M10 40 H54 L59 47 H5 Z" /><path class="am-empty-state-energy am-empty-state-face" d="M5 47 H59 L55.5 60 Q55 62 53 62 H11 Q9 62 8.5 60 Z" /><circle class="am-empty-state-energy am-empty-state-face" cx="9" cy="47.3" r="2" /><circle class="am-empty-state-energy am-empty-state-face" cx="17" cy="47.3" r="1.6" /><circle class="am-empty-state-energy am-empty-state-face" cx="25" cy="47.3" r="2.1" /><circle class="am-empty-state-energy am-empty-state-face" cx="33" cy="47.3" r="1.5" /><circle class="am-empty-state-energy am-empty-state-face" cx="41" cy="47.3" r="2" /><circle class="am-empty-state-energy am-empty-state-face" cx="49" cy="47.3" r="1.6" /><circle class="am-empty-state-energy am-empty-state-face" cx="56.5" cy="47.3" r="1.9" /><circle class="am-empty-state-hole" cx="45" cy="56" r="2.6" /><circle class="am-empty-state-hole" cx="37.5" cy="58.5" r="1.5" /><circle class="am-empty-state-hole" cx="51.5" cy="52" r="1.4" /><circle class="am-empty-state-hole" cx="27" cy="55" r="1.1" /><circle class="am-empty-state-hole" cx="18" cy="58" r="1" /></g><g class="am-empty-state-bubble am-empty-state-drop-a"><circle class="am-empty-state-energy" cx="26" cy="37" r="3.6" /><circle class="am-empty-state-hole" cx="26.86" cy="37.72" r="1.58" /></g><g class="am-empty-state-bubble am-empty-state-drop-b"><circle class="am-empty-state-energy" cx="36.5" cy="35.5" r="4.6" /><circle class="am-empty-state-hole" cx="37.6" cy="36.42" r="2.02" /></g></g><g class="am-empty-state-kind am-empty-state-kind-none"><g class="am-empty-state-bubble am-empty-state-drop-a"><circle class="am-empty-state-energy" cx="18" cy="44" r="5.4" /><circle class="am-empty-state-hole" cx="19.3" cy="45.08" r="2.38" /></g><g class="am-empty-state-bubble am-empty-state-drop-b"><circle class="am-empty-state-energy" cx="34" cy="47" r="3.8" /><circle class="am-empty-state-hole" cx="34.91" cy="47.76" r="1.67" /></g><g class="am-empty-state-bubble am-empty-state-drop-c"><circle class="am-empty-state-energy" cx="46.5" cy="41" r="4.7" /><circle class="am-empty-state-hole" cx="47.63" cy="41.94" r="2.07" /></g><circle class="am-empty-state-floor" cx="12" cy="55.5" r="0.9" /><circle class="am-empty-state-floor" cx="17" cy="55.5" r="1.3" /><circle class="am-empty-state-floor" cx="22" cy="55.5" r="0.9" /><circle class="am-empty-state-floor" cx="30" cy="55.5" r="0.7" /><circle class="am-empty-state-floor" cx="35" cy="55.5" r="1.1" /><circle class="am-empty-state-floor" cx="40" cy="55.5" r="0.7" /><circle class="am-empty-state-floor" cx="46" cy="55.5" r="1.2" /><circle class="am-empty-state-floor" cx="51" cy="55.5" r="0.8" /></g><g class="am-empty-state-kind am-empty-state-kind-error"><g class="am-empty-state-splat"><circle class="am-empty-state-energy" cx="32" cy="33" r="11.96" /><circle class="am-empty-state-energy" cx="23.16" cy="37.16" r="6.76" /><circle class="am-empty-state-energy" cx="40.32" cy="27.8" r="6.76" /><circle class="am-empty-state-energy" cx="38.24" cy="40.8" r="5.72" /><circle class="am-empty-state-energy" cx="26.8" cy="25.2" r="5.2" /><circle class="am-empty-state-hole" cx="33.04" cy="32.48" r="4.68" /><circle class="am-empty-state-hole" cx="24.2" cy="36.64" r="2.34" /></g><g class="am-empty-state-sats"><circle class="am-empty-state-energy am-empty-state-sat" cx="11.2" cy="23.64" r="3.12" /><circle class="am-empty-state-energy am-empty-state-sat" cx="53.84" cy="38.2" r="2.86" /><circle class="am-empty-state-energy am-empty-state-sat" cx="16.4" cy="50.68" r="2.6" /><circle class="am-empty-state-energy am-empty-state-sat" cx="49.16" cy="14.28" r="2.6" /><circle class="am-empty-state-energy am-empty-state-sat" cx="50.72" cy="51.72" r="2.08" /></g><g class="am-empty-state-drip"><path class="am-empty-state-drip-line" d="M24.72 42.36 V50.68" /><circle class="am-empty-state-energy" cx="24.72" cy="52.76" r="3.38" /></g></g></svg>';
  // krackle-art:empty-state:end

  function bounce(height) {
    return [
      { transform: 'translateY(' + -height + 'px)', opacity: 0, offset: 0, easing: EASE_FALL },
      { transform: 'translateY(0px)', opacity: 1, offset: 0.5, easing: EASE_RISE },
      { transform: 'translateY(' + -height * 0.22 + 'px)', opacity: 1, offset: 0.7, easing: EASE_FALL },
      { transform: 'translateY(0px)', opacity: 1, offset: 0.86, easing: EASE_RISE },
      { transform: 'translateY(' + -height * 0.06 + 'px)', opacity: 1, offset: 0.93, easing: EASE_FALL },
      { transform: 'translateY(0px)', opacity: 1, offset: 1 }
    ];
  }

  function mount(host, options) {
    if (!host || host.nodeType !== 1) throw new Error('AtelierMotion.emptyState.mount requires a DOM host.');
    var prior = mounted ? mounted.get(host) : null;
    if (prior) prior.destroy();
    if (host.childNodes.length) throw new Error('Empty state art needs an empty host.');
    var opts = options || {};
    var kind = KINDS.has(opts.kind) ? opts.kind : 'empty';
    var reducedPref = opts.reducedMotion === 'reduce' ? 'reduce' : 'system';
    var destroyed = false;
    var active = [];
    var mql = null;
    try { mql = window.matchMedia('(prefers-reduced-motion: reduce)'); } catch (_) {}

    host.setAttribute('data-atelier-motion', 'empty-state');
    host.setAttribute('data-am-kind', kind);
    host.setAttribute('aria-hidden', 'true');
    host.innerHTML = SVG_MARKUP;
    var svg = host.querySelector('svg');
    var group = host.querySelector('.am-empty-state-kind-' + kind);

    function cancel() {
      while (active.length) {
        var anim = active.pop();
        anim.onfinish = null;
        try { anim.cancel(); } catch (_) {}
      }
    }

    function run(el, frames, timing) {
      var anim = el.animate(frames, timing);
      active.push(anim);
      anim.onfinish = function () {
        anim.onfinish = null;
        try { anim.cancel(); } catch (_) {}
        active = active.filter(function (item) { return item !== anim; });
      };
    }

    function enter() {
      cancel();
      if (destroyed || reducedPref === 'reduce' || (mql && mql.matches) || document.hidden || !host.isConnected) return;
      try {
        var bubbles = group.querySelectorAll('.am-empty-state-bubble');
        if (kind === 'empty') {
          run(group.querySelector('.am-empty-state-tray'), [
            { transform: 'translateY(3px) scale(0.95)', opacity: 0.4 },
            { transform: 'translateY(-0.6px) scale(1.01)', opacity: 1, offset: 0.6 },
            { transform: 'translateY(0) scale(1)', opacity: 1 }
          ], { duration: 280, easing: EASE_STANDARD });
        }
        if (kind === 'error') {
          run(group.querySelector('.am-empty-state-splat'), [
            { transform: 'scale(0.5)', opacity: 0, offset: 0 }, { transform: 'scale(0.26)', opacity: 1, offset: 0.2 },
            { transform: 'scale(1.18)', opacity: 1, offset: 0.52 }, { transform: 'scale(0.96)', opacity: 1, offset: 0.74 },
            { transform: 'scale(1)', opacity: 1, offset: 1 }
          ], { duration: 520, easing: EASE_STANDARD });
          Array.prototype.forEach.call(group.querySelectorAll('.am-empty-state-sat'), function (sat, i) {
            run(sat, [
              { transform: 'scale(0)', opacity: 0 }, { transform: 'scale(0)', opacity: 0, offset: 0.3 },
              { transform: 'scale(1.3)', opacity: 1, offset: 0.7 }, { transform: 'scale(1)', opacity: 1 }
            ], { duration: 520 + i * 30, easing: EASE_STANDARD });
          });
          run(group.querySelector('.am-empty-state-drip'), [
            { transform: 'scaleY(0)' }, { transform: 'scaleY(0)', offset: 0.45 },
            { transform: 'scaleY(1.15)', offset: 0.82 }, { transform: 'scaleY(1)' }
          ], { duration: 640, easing: EASE_STANDARD });
        }
        Array.prototype.forEach.call(bubbles, function (bubble, i) {
          run(bubble, bounce(kind === 'none' ? 22 : 16), { duration: 460, delay: 60 + i * 70, fill: 'backwards', easing: 'linear' });
        });
      } catch (_) {
        // Static artwork is the complete fallback.
        cancel();
      }
    }

    var handle = {
      replay: enter,
      destroy: function () {
        if (destroyed) return;
        destroyed = true;
        cancel();
        if (svg && svg.parentNode === host) host.removeChild(svg);
        host.removeAttribute('data-atelier-motion');
        host.removeAttribute('data-am-kind');
        if (mounted && mounted.get(host) === handle) mounted.delete(host);
      }
    };
    if (mounted) mounted.set(host, handle);
    enter();
    return handle;
  }

  window.AtelierMotion = window.AtelierMotion || {};
  window.AtelierMotion.emptyState = {mount: mount};
})();
